/**
 * The Class Cart.
 *
 * @author Eduardo Macarron
 */
public class Cart implements java.io.Serializable {
    private static final long serialVersionUID = 8329559983943337176L;

    private final java.util.Map<java.lang.String, org.mybatis.jpetstore.domain.CartItem> itemMap = java.util.Collections.synchronizedMap(new java.util.HashMap<>());

    private final java.util.List<org.mybatis.jpetstore.domain.CartItem> itemList = new java.util.ArrayList<>();

    public java.util.Iterator<org.mybatis.jpetstore.domain.CartItem> getCartItems() {
        return itemList.iterator();
    }

    public java.util.List<org.mybatis.jpetstore.domain.CartItem> getCartItemList() {
        return itemList;
    }

    public int getNumberOfItems() {
        return itemList.size();
    }

    public java.util.Iterator<org.mybatis.jpetstore.domain.CartItem> getAllCartItems() {
        return itemList.iterator();
    }

    public boolean containsItemId(java.lang.String itemId) {
        return itemMap.containsKey(itemId);
    }

    /**
     * Adds the item.
     *
     * @param item
     * 		the item
     * @param isInStock
     * 		the is in stock
     */
    public void addItem(org.mybatis.jpetstore.domain.Item item, boolean isInStock) {
        org.mybatis.jpetstore.domain.CartItem cartItem = itemMap.get(item.getItemId());
        if (cartItem == null) {
            cartItem = new org.mybatis.jpetstore.domain.CartItem();
            cartItem.setItem(item);
            cartItem.setQuantity(0);
            cartItem.setInStock(isInStock);
            itemMap.put(item.getItemId(), cartItem);
            itemList.add(cartItem);
        }
        cartItem.incrementQuantity();
    }

    /**
     * Removes the item by id.
     *
     * @param itemId
     * 		the item id
     * @return the item
     */
    public org.mybatis.jpetstore.domain.Item removeItemById(java.lang.String itemId) {
        org.mybatis.jpetstore.domain.CartItem cartItem = itemMap.remove(itemId);
        if (cartItem == null) {
            return null;
        } else {
            itemList.remove(cartItem);
            return cartItem.getItem();
        }
    }

    /**
     * Increment quantity by item id.
     *
     * @param itemId
     * 		the item id
     */
    public void incrementQuantityByItemId(java.lang.String itemId) {
        org.mybatis.jpetstore.domain.CartItem cartItem = itemMap.get(itemId);
        cartItem.incrementQuantity();
    }

    public void setQuantityByItemId(java.lang.String itemId, int quantity) {
        org.mybatis.jpetstore.domain.CartItem cartItem = itemMap.get(itemId);
        cartItem.setQuantity(quantity);
    }

    /**
     * Gets the sub total.
     *
     * @return the sub total
     */
    public java.math.BigDecimal getSubTotal() {
        return itemList.stream().map(cartItem -> cartItem.getItem().getListPrice().multiply(new java.math.BigDecimal(cartItem.getQuantity()))).reduce(java.math.BigDecimal.ZERO, java.math.BigDecimal::add);
    }
}

/**
 * The Class CartItem.
 *
 * @author Eduardo Macarron
 */
public class CartItem implements java.io.Serializable {
    private static final long serialVersionUID = 6620528781626504362L;

    private org.mybatis.jpetstore.domain.Item item;

    private int quantity;

    private boolean inStock;

    private java.math.BigDecimal total;

    public boolean isInStock() {
        return inStock;
    }

    public void setInStock(boolean inStock) {
        this.inStock = inStock;
    }

    public java.math.BigDecimal getTotal() {
        return total;
    }

    public org.mybatis.jpetstore.domain.Item getItem() {
        return item;
    }

    public void setItem(org.mybatis.jpetstore.domain.Item item) {
        this.item = item;
        calculateTotal();
    }

    public int getQuantity() {
        return quantity;
    }

    public void setQuantity(int quantity) {
        this.quantity = quantity;
        calculateTotal();
    }

    public void incrementQuantity() {
        quantity++;
        calculateTotal();
    }

    private void calculateTotal() {
        total = java.util.Optional.ofNullable(item).map(org.mybatis.jpetstore.domain.Item::getListPrice).map(v -> v.multiply(new java.math.BigDecimal(quantity))).orElse(null);
    }
}

class CartTest {
    @org.junit.jupiter.api.Test
    void addItemWhenIsInStockIsTrue() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
        item.setItemId("I01");
        item.setListPrice(new java.math.BigDecimal("2.05"));
        // when
        cart.addItem(item, true);
        cart.addItem(item, true);
        // then
        assertThat(cart.getCartItemList().get(0).getItem()).isSameAs(item);
        assertThat(cart.getCartItemList().get(0).isInStock()).isTrue();
        assertThat(cart.getCartItemList().get(0).getQuantity()).isEqualTo(2);
        assertThat(cart.getCartItemList().get(0).getTotal()).isEqualTo(new java.math.BigDecimal("4.10"));
        assertThat(cart.containsItemId("I01")).isTrue();
        assertThat(cart.getNumberOfItems()).isEqualTo(1);
        {
            java.util.Iterator<org.mybatis.jpetstore.domain.CartItem> cartItems = cart.getCartItems();
            assertThat(cartItems.next()).isNotNull();
            assertThat(cartItems.hasNext()).isFalse();
        }
        {
            java.util.Iterator<org.mybatis.jpetstore.domain.CartItem> cartItems = cart.getAllCartItems();
            assertThat(cartItems.next()).isNotNull();
            assertThat(cartItems.hasNext()).isFalse();
        }
    }

    @org.junit.jupiter.api.Test
    void addItemWhenIsInStockIsFalse() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
        item.setItemId("I01");
        item.setListPrice(new java.math.BigDecimal("2.05"));
        // when
        cart.addItem(item, false);
        // then
        assertThat(cart.getCartItemList().get(0).getItem()).isSameAs(item);
        assertThat(cart.getCartItemList().get(0).isInStock()).isFalse();
        assertThat(cart.getCartItemList().get(0).getQuantity()).isEqualTo(1);
        assertThat(cart.getCartItemList().get(0).getTotal()).isEqualTo(new java.math.BigDecimal("2.05"));
    }

    @org.junit.jupiter.api.Test
    void removeItemByIdWhenItemNotFound() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        // when
        org.mybatis.jpetstore.domain.Item item = cart.removeItemById("I01");
        // then
        assertThat(item).isNull();
        assertThat(cart.containsItemId("I01")).isFalse();
        assertThat(cart.getNumberOfItems()).isEqualTo(0);
        assertThat(cart.getCartItems().hasNext()).isFalse();
        assertThat(cart.getAllCartItems().hasNext()).isFalse();
    }

    @org.junit.jupiter.api.Test
    void removeItemByIdWhenItemFound() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
        item.setItemId("I01");
        item.setListPrice(new java.math.BigDecimal("2.05"));
        cart.addItem(item, true);
        // when
        org.mybatis.jpetstore.domain.Item removedItem = cart.removeItemById("I01");
        // then
        assertThat(removedItem).isSameAs(item);
        assertThat(cart.getCartItemList()).isEmpty();
    }

    @org.junit.jupiter.api.Test
    void incrementQuantityByItemId() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
        item.setItemId("I01");
        item.setListPrice(new java.math.BigDecimal("2.05"));
        cart.addItem(item, true);
        // when
        cart.incrementQuantityByItemId("I01");
        cart.incrementQuantityByItemId("I01");
        // then
        assertThat(cart.getCartItemList().get(0).getItem()).isSameAs(item);
        assertThat(cart.getCartItemList().get(0).isInStock()).isTrue();
        assertThat(cart.getCartItemList().get(0).getQuantity()).isEqualTo(3);
        assertThat(cart.getCartItemList().get(0).getTotal()).isEqualTo(new java.math.BigDecimal("6.15"));
    }

    @org.junit.jupiter.api.Test
    void setQuantityByItemId() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
        item.setItemId("I01");
        item.setListPrice(new java.math.BigDecimal("2.05"));
        cart.addItem(item, true);
        // when
        cart.setQuantityByItemId("I01", 10);
        // then
        assertThat(cart.getCartItemList().get(0).getItem()).isSameAs(item);
        assertThat(cart.getCartItemList().get(0).isInStock()).isTrue();
        assertThat(cart.getCartItemList().get(0).getQuantity()).isEqualTo(10);
        assertThat(cart.getCartItemList().get(0).getTotal()).isEqualTo(new java.math.BigDecimal("20.50"));
    }

    @org.junit.jupiter.api.Test
    void getSubTotalWhenItemIsEmpty() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        // when
        java.math.BigDecimal subTotal = cart.getSubTotal();
        // then
        assertThat(subTotal).isEqualTo(java.math.BigDecimal.ZERO);
    }

    @org.junit.jupiter.api.Test
    void getSubTotalWhenItemIsExist() {
        // given
        org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();
        {
            org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
            item.setItemId("I01");
            item.setListPrice(new java.math.BigDecimal("2.05"));
            cart.addItem(item, true);
            cart.setQuantityByItemId("I01", 5);
        }
        {
            org.mybatis.jpetstore.domain.Item item = new org.mybatis.jpetstore.domain.Item();
            item.setItemId("I02");
            item.setListPrice(new java.math.BigDecimal("3.06"));
            cart.addItem(item, true);
            cart.setQuantityByItemId("I02", 6);
        }
        // when
        java.math.BigDecimal subTotal = cart.getSubTotal();
        // then
        assertThat(subTotal).isEqualTo(new java.math.BigDecimal("28.61"));
    }
}

