@org.springframework.context.annotation.Configuration
@org.mybatis.spring.annotation.MapperScan("org.mybatis.jpetstore.mapper")
public class MapperTestContext {
    @org.springframework.context.annotation.Bean
    javax.sql.DataSource dataSource() {
        return new org.springframework.jdbc.datasource.embedded.EmbeddedDatabaseBuilder().generateUniqueName(true).setType(EmbeddedDatabaseType.HSQL).setScriptEncoding("UTF-8").ignoreFailedDrops(true).addScript("database/jpetstore-hsqldb-schema.sql").addScripts("database/jpetstore-hsqldb-dataload.sql").build();
    }

    @org.springframework.context.annotation.Bean
    org.springframework.transaction.PlatformTransactionManager transactionManager() {
        return new org.springframework.jdbc.datasource.DataSourceTransactionManager(dataSource());
    }

    @org.springframework.context.annotation.Bean
    org.mybatis.spring.SqlSessionFactoryBean sqlSessionFactory() {
        org.mybatis.spring.SqlSessionFactoryBean factoryBean = new org.mybatis.spring.SqlSessionFactoryBean();
        factoryBean.setDataSource(dataSource());
        factoryBean.setTypeAliasesPackage("org.mybatis.jpetstore.domain");
        return factoryBean;
    }

    @org.springframework.context.annotation.Bean
    org.springframework.jdbc.core.JdbcTemplate jdbcTemplate() {
        return new org.springframework.jdbc.core.JdbcTemplate(dataSource());
    }
}

