        this.categoryMapper = categoryMapper;
        this.itemMapper = itemMapper;
        this.productMapper = productMapper;
    }

    public java.util.List<org.mybatis.jpetstore.domain.Category> getCategoryList() {
        return categoryMapper.getCategoryList();
    }

    public org.mybatis.jpetstore.domain.Category getCategory(java.lang.String categoryId) {
        return categoryMapper.getCategory(categoryId);
    }

    public org.mybatis.jpetstore.domain.Product getProduct(java.lang.String productId) {
        return productMapper.getProduct(productId);
    }

    public java.util.List<org.mybatis.jpetstore.domain.Product> getProductListByCategory(java.lang.String categoryId) {
        return productMapper.getProductListByCategory(categoryId);
    }

    /**
     * Search product list.
     *
     * @param keywords
     * 		the keywords
     * @return the list
     */
    public java.util.List<org.mybatis.jpetstore.domain.Product> searchProductList(java.lang.String keywords) {
        java.util.List<org.mybatis.jpetstore.domain.Product> products = new java.util.ArrayList<>();
        for (java.lang.String keyword : keywords.split("\\s+")) {
            products.addAll(productMapper.searchProductList(("%" + keyword.toLowerCase()) + "%"));
        }
        return products;
    }

    public java.util.List<org.mybatis.jpetstore.domain.Item> getItemListByProduct(java.lang.String productId) {
        return itemMapper.getItemListByProduct(productId);
    }

    public org.mybatis.jpetstore.domain.Item getItem(java.lang.String itemId) {
        return itemMapper.getItem(itemId);
    }

    public boolean isItemInStock(java.lang.String itemId) {
        return itemMapper.getInventoryQuantity(itemId) > 0;
    }
}

