/**
 * The Class OrderService.
 *
 * @author Eduardo Macarron
 */
@org.springframework.stereotype.Service
public class OrderService {
    private final org.mybatis.jpetstore.mapper.ItemMapper itemMapper;

    private final org.mybatis.jpetstore.mapper.OrderMapper orderMapper;

    private final org.mybatis.jpetstore.mapper.SequenceMapper sequenceMapper;

    private final org.mybatis.jpetstore.mapper.LineItemMapper lineItemMapper;

    public OrderService(org.mybatis.jpetstore.mapper.ItemMapper itemMapper, org.mybatis.jpetstore.mapper.OrderMapper orderMapper, org.mybatis.jpetstore.mapper.SequenceMapper sequenceMapper, org.mybatis.jpetstore.mapper.LineItemMapper lineItemMapper) {
        this.itemMapper = itemMapper;
        this.orderMapper = orderMapper;
        this.sequenceMapper = sequenceMapper;
        this.lineItemMapper = lineItemMapper;
    }

    /**
     * Insert order.
     *
     * @param order
     * 		the order
     */
    @org.springframework.transaction.annotation.Transactional
    public void insertOrder(org.mybatis.jpetstore.domain.Order order) {
        order.setOrderId(getNextId("ordernum"));
        order.getLineItems().forEach(lineItem -> {
            java.lang.String itemId = lineItem.getItemId();
            java.lang.Integer increment = lineItem.getQuantity();
            java.util.Map<java.lang.String, java.lang.Object> param = new java.util.HashMap<>(2);
            param.put("itemId", itemId);
            param.put("increment", increment);
            itemMapper.updateInventoryQuantity(param);
        });
        orderMapper.insertOrder(order);
        orderMapper.insertOrderStatus(order);
        order.getLineItems().forEach(lineItem -> {
            lineItem.setOrderId(order.getOrderId());
            lineItemMapper.insertLineItem(lineItem);
        });
    }

    /**
     * Gets the order.
     *
     * @param orderId
     * 		the order id
     * @return the order
     */
    @org.springframework.transaction.annotation.Transactional
    public org.mybatis.jpetstore.domain.Order getOrder(int orderId) {
        org.mybatis.jpetstore.domain.Order order = orderMapper.getOrder(orderId);
        order.setLineItems(lineItemMapper.getLineItemsByOrderId(orderId));
        order.getLineItems().forEach(lineItem -> {
            org.mybatis.jpetstore.domain.Item item = itemMapper.getItem(lineItem.getItemId());
            item.setQuantity(itemMapper.getInventoryQuantity(lineItem.getItemId()));
            lineItem.setItem(item);
        });
        return order;
    }

    /**
     * Gets the orders by username.
     *
     * @param username
     * 		the username
     * @return the orders by username
     */
    public java.util.List<org.mybatis.jpetstore.domain.Order> getOrdersByUsername(java.lang.String username) {
        return orderMapper.getOrdersByUsername(username);
    }

    /**
     * Gets the next id.
     *
     * @param name
     * 		the name
     * @return the next id
     */
    public int getNextId(java.lang.String name) {
        org.mybatis.jpetstore.domain.Sequence sequence = sequenceMapper.getSequence(new org.mybatis.jpetstore.domain.Sequence(name, -1));
        if (sequence == null) {
            throw new java.lang.RuntimeException(("Error: A null sequence was returned from the database (could not get next " + name) + " sequence).");
        }
        org.mybatis.jpetstore.domain.Sequence parameterObject = new org.mybatis.jpetstore.domain.Sequence(name, sequence.getNextId() + 1);
        sequenceMapper.updateSequence(parameterObject);
        return sequence.getNextId();
    }
}

