    private org.mybatis.jpetstore.mapper.SequenceMapper sequenceMapper;

    @org.mockito.InjectMocks
    private org.mybatis.jpetstore.service.OrderService orderService;

    @org.junit.jupiter.api.Test
    void shouldReturnOrderWhenGivenOrderIdWithOutLineItems() {
        // given
        int orderId = 1;
        org.mybatis.jpetstore.domain.Order order = new org.mybatis.jpetstore.domain.Order();
        java.util.List<org.mybatis.jpetstore.domain.LineItem> lineItems = new java.util.ArrayList<>();
        // when
        Mockito.when(orderMapper.getOrder(orderId)).thenReturn(order);
        Mockito.when(lineItemMapper.getLineItemsByOrderId(orderId)).thenReturn(lineItems);
        // then
        assertThat(orderService.getOrder(orderId)).isEqualTo(order);
        assertThat(orderService.getOrder(orderId).getLineItems()).isEmpty();
    }

    @org.junit.jupiter.api.Test
    void shouldReturnOrderWhenGivenOrderIdExistedLineItems() {
        // given
        int orderId = 1;
        org.mybatis.jpetstore.domain.Order order = new org.mybatis.jpetstore.domain.Order();
        java.util.List<org.mybatis.jpetstore.domain.LineItem> lineItems = new java.util.ArrayList<>();
        org.mybatis.jpetstore.domain.LineItem item = new org.mybatis.jpetstore.domain.LineItem();
        java.lang.String itemId = "abc";
        item.setItemId(itemId);
        lineItems.add(item);
        // when
        Mockito.when(orderMapper.getOrder(orderId)).thenReturn(order);
        Mockito.when(lineItemMapper.getLineItemsByOrderId(orderId)).thenReturn(lineItems);
        Mockito.when(itemMapper.getItem(itemId)).thenReturn(new org.mybatis.jpetstore.domain.Item());
        Mockito.when(itemMapper.getInventoryQuantity(itemId)).thenReturn(5);
        // then
        org.mybatis.jpetstore.domain.Order expectedOrder = orderService.getOrder(orderId);
        assertThat(expectedOrder).isEqualTo(order);
        assertThat(expectedOrder.getLineItems()).hasSize(1);
        assertThat(expectedOrder.getLineItems().get(0).getItem().getQuantity()).isEqualTo(5);
    }

    @org.junit.jupiter.api.Test
    void shouldReturnOrderList() {
        // given
        java.lang.String username = "foo";
        java.util.List<org.mybatis.jpetstore.domain.Order> expectedOrders = new java.util.ArrayList<>();
        // when
        Mockito.when(orderMapper.getOrdersByUsername(username)).thenReturn(expectedOrders);
        java.util.List<org.mybatis.jpetstore.domain.Order> orders = orderService.getOrdersByUsername(username);
        // then
        assertThat(orders).isSameAs(expectedOrders);
    }

    @org.junit.jupiter.api.Test
    void shouldReturnNextId() {
        // given
        org.mybatis.jpetstore.domain.Sequence expectedSequence = new org.mybatis.jpetstore.domain.Sequence("order", 100);
        // when
        Mockito.when(sequenceMapper.getSequence(any())).thenReturn(expectedSequence);
        int nextId = orderService.getNextId("order");
        // then
        assertThat(nextId).isEqualTo(100);
        Mockito.verify(sequenceMapper).getSequence(argThat(v -> v.getName().equals("order") && (v.getNextId() == (-1))));
        Mockito.verify(sequenceMapper).updateSequence(argThat(v -> v.getName().equals("order") && (v.getNextId() == 101)));
    }

    @org.junit.jupiter.api.Test
    void shouldThrowExceptionWhenSequenceNotFound() {
        // given
        // when
        Mockito.when(sequenceMapper.getSequence(any())).thenReturn(null);
        try {
            orderService.getNextId("order");
            fail("Should throw an exception when sequence not found.");
        } catch (java.lang.RuntimeException e) {
            // then
            assertThat(e.getMessage()).isEqualTo("Error: A null sequence was returned from the database (could not get next order sequence).");
            Mockito.verify(sequenceMapper).getSequence(argThat(v -> v.getName().equals("order") && (v.getNextId() == (-1))));
        }
    }

    @org.junit.jupiter.api.Test
    void shouldCallTheMapperToInsert() {
        // given
        org.mybatis.jpetstore.domain.Order order = new org.mybatis.jpetstore.domain.Order();
        org.mybatis.jpetstore.domain.LineItem item = new org.mybatis.jpetstore.domain.LineItem();
        java.lang.String itemId = "I01";
        int quantity = 4;
        item.setItemId(itemId);
        item.setQuantity(quantity);
        order.addLineItem(item);
        org.mybatis.jpetstore.domain.Sequence orderNumSequence = new org.mybatis.jpetstore.domain.Sequence("ordernum", 100);
        java.util.Map<java.lang.String, java.lang.Object> expectedItemParam = new java.util.HashMap<>(2);
        expectedItemParam.put("itemId", itemId);
        expectedItemParam.put("increment", quantity);
        // when
        Mockito.when(sequenceMapper.getSequence(any())).thenReturn(orderNumSequence);
        orderService.insertOrder(order);
        // then
        Mockito.verify(orderMapper).insertOrder(argThat(v -> (v == order) && (v.getOrderId() == 100)));
        Mockito.verify(orderMapper).insertOrderStatus(eq(order));
        Mockito.verify(lineItemMapper).insertLineItem(argThat(v -> (v == item) && (v.getOrderId() == 100)));
        Mockito.verify(itemMapper).updateInventoryQuantity(eq(expectedItemParam));
    }
}

