    private static final java.lang.String NEW_ACCOUNT = "/WEB-INF/jsp/account/NewAccountForm.jsp";

    private static final java.lang.String EDIT_ACCOUNT = "/WEB-INF/jsp/account/EditAccountForm.jsp";

    private static final java.lang.String SIGNON = "/WEB-INF/jsp/account/SignonForm.jsp";

    private static final java.util.List<java.lang.String> LANGUAGE_LIST;

    private static final java.util.List<java.lang.String> CATEGORY_LIST;

    @net.sourceforge.stripes.integration.spring.SpringBean
    private transient org.mybatis.jpetstore.service.AccountService accountService;

    @net.sourceforge.stripes.integration.spring.SpringBean
    private transient org.mybatis.jpetstore.service.CatalogService catalogService;

    private org.mybatis.jpetstore.domain.Account account = new org.mybatis.jpetstore.domain.Account();

