    private boolean authenticated;

    static {
        LANGUAGE_LIST = java.util.Collections.unmodifiableList(java.util.Arrays.asList("english", "japanese"));
        CATEGORY_LIST = java.util.Collections.unmodifiableList(java.util.Arrays.asList("FISH", "DOGS", "REPTILES", "CATS", "BIRDS"));
