/**
 * The Class CartActionBean.
 *
 * @author Eduardo Macarron
 */
@net.sourceforge.stripes.action.SessionScope
public class CartActionBean extends org.mybatis.jpetstore.web.actions.AbstractActionBean {
    private static final long serialVersionUID = -4038684592582714235L;

    private static final java.lang.String VIEW_CART = "/WEB-INF/jsp/cart/Cart.jsp";

    private static final java.lang.String CHECK_OUT = "/WEB-INF/jsp/cart/Checkout.jsp";

    @net.sourceforge.stripes.integration.spring.SpringBean
    private transient org.mybatis.jpetstore.service.CatalogService catalogService;

    private org.mybatis.jpetstore.domain.Cart cart = new org.mybatis.jpetstore.domain.Cart();

    private java.lang.String workingItemId;

    public org.mybatis.jpetstore.domain.Cart getCart() {
        return cart;
    }

    public void setCart(org.mybatis.jpetstore.domain.Cart cart) {
        this.cart = cart;
    }

    public void setWorkingItemId(java.lang.String workingItemId) {
        this.workingItemId = workingItemId;
    }

    /**
     * Adds the item to cart.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution addItemToCart() {
        if (cart.containsItemId(workingItemId)) {
            cart.incrementQuantityByItemId(workingItemId);
        } else {
            // isInStock is a "real-time" property that must be updated
            // every time an item is added to the cart, even if other
            // item details are cached.
            boolean isInStock = catalogService.isItemInStock(workingItemId);
            org.mybatis.jpetstore.domain.Item item = catalogService.getItem(workingItemId);
            cart.addItem(item, isInStock);
        }
        return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.CartActionBean.VIEW_CART);
    }

    /**
     * Removes the item from cart.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution removeItemFromCart() {
        org.mybatis.jpetstore.domain.Item item = cart.removeItemById(workingItemId);
        if (item == null) {
            setMessage("Attempted to remove null CartItem from Cart.");
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.AbstractActionBean.ERROR);
        } else {
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.CartActionBean.VIEW_CART);
        }
    }

    /**
     * Update cart quantities.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution updateCartQuantities() {
        javax.servlet.http.HttpServletRequest request = context.getRequest();
        java.util.Iterator<org.mybatis.jpetstore.domain.CartItem> cartItems = getCart().getAllCartItems();
        while (cartItems.hasNext()) {
            org.mybatis.jpetstore.domain.CartItem cartItem = cartItems.next();
            java.lang.String itemId = cartItem.getItem().getItemId();
            try {
                int quantity = java.lang.Integer.parseInt(request.getParameter(itemId));
                getCart().setQuantityByItemId(itemId, quantity);
                if (quantity < 1) {
                    cartItems.remove();
                }
            } catch (java.lang.Exception e) {
                // ignore parse exceptions on purpose
            }
        } 
        return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.CartActionBean.VIEW_CART);
    }

    public net.sourceforge.stripes.action.ForwardResolution viewCart() {
        return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.CartActionBean.VIEW_CART);
    }

    public net.sourceforge.stripes.action.ForwardResolution checkOut() {
        return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.CartActionBean.CHECK_OUT);
    }

    public void clear() {
        cart = new org.mybatis.jpetstore.domain.Cart();
        workingItemId = null;
    }
}

