 */
@net.sourceforge.stripes.action.SessionScope
public class OrderActionBean extends org.mybatis.jpetstore.web.actions.AbstractActionBean {
    private static final long serialVersionUID = -6171288227470176272L;

    private static final java.lang.String CONFIRM_ORDER = "/WEB-INF/jsp/order/ConfirmOrder.jsp";

    private static final java.lang.String LIST_ORDERS = "/WEB-INF/jsp/order/ListOrders.jsp";

    private static final java.lang.String NEW_ORDER = "/WEB-INF/jsp/order/NewOrderForm.jsp";

    private static final java.lang.String SHIPPING = "/WEB-INF/jsp/order/ShippingForm.jsp";

    private static final java.lang.String VIEW_ORDER = "/WEB-INF/jsp/order/ViewOrder.jsp";

    private static final java.util.List<java.lang.String> CARD_TYPE_LIST;

    @net.sourceforge.stripes.integration.spring.SpringBean
    private transient org.mybatis.jpetstore.service.OrderService orderService;

    private org.mybatis.jpetstore.domain.Order order = new org.mybatis.jpetstore.domain.Order();

    private boolean shippingAddressRequired;

    private boolean confirmed;

    private java.util.List<org.mybatis.jpetstore.domain.Order> orderList;

    static {
        CARD_TYPE_LIST = java.util.Collections.unmodifiableList(java.util.Arrays.asList("Visa", "MasterCard", "American Express"));
    }

    public int getOrderId() {
        return order.getOrderId();
    }

    public void setOrderId(int orderId) {
        order.setOrderId(orderId);
    }

    public org.mybatis.jpetstore.domain.Order getOrder() {
        return order;
    }

    public void setOrder(org.mybatis.jpetstore.domain.Order order) {
        this.order = order;
    }

    public boolean isShippingAddressRequired() {
        return shippingAddressRequired;
    }

    public void setShippingAddressRequired(boolean shippingAddressRequired) {
        this.shippingAddressRequired = shippingAddressRequired;
    }

    public boolean isConfirmed() {
        return confirmed;
    }

    public void setConfirmed(boolean confirmed) {
        this.confirmed = confirmed;
    }

    public java.util.List<java.lang.String> getCreditCardTypes() {
        return org.mybatis.jpetstore.web.actions.OrderActionBean.CARD_TYPE_LIST;
    }

    public java.util.List<org.mybatis.jpetstore.domain.Order> getOrderList() {
        return orderList;
    }

    /**
     * List orders.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution listOrders() {
        javax.servlet.http.HttpSession session = context.getRequest().getSession();
        org.mybatis.jpetstore.web.actions.AccountActionBean accountBean = ((org.mybatis.jpetstore.web.actions.AccountActionBean) (session.getAttribute("/actions/Account.action")));
        orderList = orderService.getOrdersByUsername(accountBean.getAccount().getUsername());
        return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.OrderActionBean.LIST_ORDERS);
    }

    /**
     * New order form.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution newOrderForm() {
        javax.servlet.http.HttpSession session = context.getRequest().getSession();
        org.mybatis.jpetstore.web.actions.AccountActionBean accountBean = ((org.mybatis.jpetstore.web.actions.AccountActionBean) (session.getAttribute("/actions/Account.action")));
        org.mybatis.jpetstore.web.actions.CartActionBean cartBean = ((org.mybatis.jpetstore.web.actions.CartActionBean) (session.getAttribute("/actions/Cart.action")));
        clear();
        if ((accountBean == null) || (!accountBean.isAuthenticated())) {
            setMessage("You must sign on before attempting to check out.  Please sign on and try checking out again.");
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.AccountActionBean.class);
        } else if (cartBean != null) {
            order.initOrder(accountBean.getAccount(), cartBean.getCart());
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.OrderActionBean.NEW_ORDER);
        } else {
            setMessage("An order could not be created because a cart could not be found.");
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.AbstractActionBean.ERROR);
        }
    }

    /**
     * New order.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution newOrder() {
        javax.servlet.http.HttpSession session = context.getRequest().getSession();
        if (shippingAddressRequired) {
            shippingAddressRequired = false;
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.OrderActionBean.SHIPPING);
        } else if (!isConfirmed()) {
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.OrderActionBean.CONFIRM_ORDER);
        } else if (getOrder() != null) {
            orderService.insertOrder(order);
            org.mybatis.jpetstore.web.actions.CartActionBean cartBean = ((org.mybatis.jpetstore.web.actions.CartActionBean) (session.getAttribute("/actions/Cart.action")));
            cartBean.clear();
            setMessage("Thank you, your order has been submitted.");
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.OrderActionBean.VIEW_ORDER);
        } else {
            setMessage("An error occurred processing your order (order was null).");
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.AbstractActionBean.ERROR);
        }
    }

    /**
     * View order.
     *
     * @return the resolution
     */
    public net.sourceforge.stripes.action.Resolution viewOrder() {
        javax.servlet.http.HttpSession session = context.getRequest().getSession();
        org.mybatis.jpetstore.web.actions.AccountActionBean accountBean = ((org.mybatis.jpetstore.web.actions.AccountActionBean) (session.getAttribute("accountBean")));
        order = orderService.getOrder(order.getOrderId());
        if (accountBean.getAccount().getUsername().equals(order.getUsername())) {
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.OrderActionBean.VIEW_ORDER);
        } else {
            order = null;
            setMessage("You may only view your own orders.");
            return new net.sourceforge.stripes.action.ForwardResolution(org.mybatis.jpetstore.web.actions.AbstractActionBean.ERROR);
        }
    }

    /**
     * Clear.
     */
    public void clear() {
        order = new org.mybatis.jpetstore.domain.Order();
        shippingAddressRequired = false;
        confirmed = false;
        orderList = null;
    }
}

