    private static java.lang.String extractOrderId(java.lang.String target) {
        java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("Order #(\\d{4}) .*").matcher(target);
        java.lang.String orderId = "";
        if (matcher.find()) {
            orderId = matcher.group(1);
        }
        return orderId;
    }
