public final class MavenWrapperDownloader {
    private static final java.lang.String WRAPPER_VERSION = "3.1.1";

    private static final boolean VERBOSE = java.lang.Boolean.parseBoolean(java.lang.System.getenv("MVNW_VERBOSE"));

    /**
     * Default URL to download the maven-wrapper.jar from, if no 'downloadUrl' is provided.
     */
    private static final java.lang.String DEFAULT_DOWNLOAD_URL = ((("https://repo.maven.apache.org/maven2/org/apache/maven/wrapper/maven-wrapper/" + MavenWrapperDownloader.WRAPPER_VERSION) + "/maven-wrapper-") + MavenWrapperDownloader.WRAPPER_VERSION) + ".jar";

    /**
     * Path to the maven-wrapper.properties file, which might contain a downloadUrl property to use instead of the
     * default one.
     */
    private static final java.lang.String MAVEN_WRAPPER_PROPERTIES_PATH = ".mvn/wrapper/maven-wrapper.properties";

    /**
     * Path where the maven-wrapper.jar will be saved to.
     */
    private static final java.lang.String MAVEN_WRAPPER_JAR_PATH = ".mvn/wrapper/maven-wrapper.jar";

    /**
     * Name of the property which should be used to override the default download url for the wrapper.
     */
    private static final java.lang.String PROPERTY_NAME_WRAPPER_URL = "wrapperUrl";

    public static void main(java.lang.String[] args) {
        if (args.length == 0) {
            java.lang.System.err.println(" - ERROR projectBasedir parameter missing");
            java.lang.System.exit(1);
        }
        MavenWrapperDownloader.log(" - Downloader started");
        final java.lang.String dir = args[0].replace("..", "");// Sanitize path

        final java.nio.file.Path projectBasedir = java.nio.file.Paths.get(dir).toAbsolutePath().normalize();
        if (!java.nio.file.Files.isDirectory(projectBasedir, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
            java.lang.System.err.println(" - ERROR projectBasedir not exists: " + projectBasedir);
            java.lang.System.exit(1);
        }
        MavenWrapperDownloader.log(" - Using base directory: " + projectBasedir);
        // If the maven-wrapper.properties exists, read it and check if it contains a custom
        // wrapperUrl parameter.
        java.nio.file.Path mavenWrapperPropertyFile = projectBasedir.resolve(MavenWrapperDownloader.MAVEN_WRAPPER_PROPERTIES_PATH);
        java.lang.String url = MavenWrapperDownloader.readWrapperUrl(mavenWrapperPropertyFile);
        try {
            java.nio.file.Path outputFile = projectBasedir.resolve(MavenWrapperDownloader.MAVEN_WRAPPER_JAR_PATH);
            MavenWrapperDownloader.createDirectories(outputFile.getParent());
            MavenWrapperDownloader.downloadFileFromURL(url, outputFile);
            MavenWrapperDownloader.log("Done");
            java.lang.System.exit(0);
        } catch (java.io.IOException e) {
            java.lang.System.err.println("- Error downloading");
            e.printStackTrace();
            java.lang.System.exit(1);
        }
    }

    private static void downloadFileFromURL(java.lang.String urlString, java.nio.file.Path destination) throws java.io.IOException {
        MavenWrapperDownloader.log(" - Downloading to: " + destination);
        if ((java.lang.System.getenv("MVNW_USERNAME") != null) && (java.lang.System.getenv("MVNW_PASSWORD") != null)) {
            final java.lang.String username = java.lang.System.getenv("MVNW_USERNAME");
            final char[] password = java.lang.System.getenv("MVNW_PASSWORD").toCharArray();
            java.net.Authenticator.setDefault(new java.net.Authenticator() {
                @java.lang.Override
                protected java.net.PasswordAuthentication getPasswordAuthentication() {
                    return new java.net.PasswordAuthentication(username, password);
                }
            });
        }
        java.net.URL website = new java.net.URL(urlString);
        try (java.io.InputStream inStream = website.openStream()) {
            java.nio.file.Files.copy(inStream, destination, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        }
        MavenWrapperDownloader.log(" - Downloader complete");
    }

    private static void createDirectories(java.nio.file.Path outputPath) throws java.io.IOException {
        if (!java.nio.file.Files.isDirectory(outputPath, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
            java.nio.file.Path createDirectories = java.nio.file.Files.createDirectories(outputPath);
            MavenWrapperDownloader.log(" - Directories created: " + createDirectories);
        }
    }

    private static java.lang.String readWrapperUrl(java.nio.file.Path mavenWrapperPropertyFile) {
        java.lang.String url = MavenWrapperDownloader.DEFAULT_DOWNLOAD_URL;
        if (java.nio.file.Files.exists(mavenWrapperPropertyFile, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
            MavenWrapperDownloader.log(" - Reading property file: " + mavenWrapperPropertyFile);
            try (java.io.InputStream in = java.nio.file.Files.newInputStream(mavenWrapperPropertyFile, java.nio.file.StandardOpenOption.READ)) {
                java.util.Properties mavenWrapperProperties = new java.util.Properties();
                mavenWrapperProperties.load(in);
                url = mavenWrapperProperties.getProperty(MavenWrapperDownloader.PROPERTY_NAME_WRAPPER_URL, MavenWrapperDownloader.DEFAULT_DOWNLOAD_URL);
            } catch (java.io.IOException e) {
                java.lang.System.err.println((" - ERROR loading '" + MavenWrapperDownloader.MAVEN_WRAPPER_PROPERTIES_PATH) + "'");
            }
        }
        MavenWrapperDownloader.log(" - Downloading from: " + url);
        return url;
    }

    private static void log(java.lang.String msg) {
        if (MavenWrapperDownloader.VERBOSE) {
            java.lang.System.out.println(msg);
        }
    }
}
